// Category B: no behaviour beyond keeping focus clear of itself. The in-page sibling of SiteHeader
// and DockedBar: a bar that sticks to the top of the window while the content after it scrolls under,
// on the page's own fill with an edge below. It owns the look a pinned control row needs, which a
// Block may not set (block-contract.md § 5). The fill runs edge to edge of the page frame while the
// content stays on the page's column, as Band's does; so, like Band, it assumes a centred column.
// It sticks within its parent, so it is placed as a child of the box that holds what scrolls under it.
import type { CSSProperties, HTMLAttributes, Ref } from "react";
import { useScrollClearance } from "./useScrollClearance";
import "./StickyBar.css";

export interface StickyBarProps extends Omit<HTMLAttributes<HTMLDivElement>, "className"> {
  className?: string;
  style?: CSSProperties;
  ref?: Ref<HTMLDivElement>;
}

export function StickyBar({ className, children, ref, ...props }: StickyBarProps) {
  // The bar covers the top of the window once it sticks, so the document keeps focus clear of it
  // (WCAG 2.4.11).
  const clearRef = useScrollClearance("start", ref);

  return (
    <div {...props} ref={clearRef} className={className ? `sd-sticky-bar ${className}` : "sd-sticky-bar"}>
      {children}
    </div>
  );
}

/* StickyBar.css — .sd-sticky-bar
   Sticks to the top of the window inside its parent, on the page's own fill with a decorative edge
   below. The fill takes one frame width (`100cqi`: AppShell's panel, the viewport where there is
   none) pulled back by the difference between frame and column, and gives that difference back as
   inline padding, so the content starts where the column does (Band's construction). */
.sd-sticky-bar {
  position: sticky;
  inset-block-start: 0;
  z-index: var(--sd-sticky-bar-z-index);
  width: 100cqi;
  margin-inline-start: calc(50% - 50cqi);
  padding-inline: calc(50cqi - 50%);
  padding-block: var(--sd-sticky-bar-padding-block);
  background: var(--sd-sticky-bar-background);
  border-block-end: var(--sd-sticky-bar-border-width) solid var(--sd-sticky-bar-border);
}
